#!/bin/bash
set -euo pipefail
mkdir -p /work/frontier
cd /work/frontier
base64 -d > config.json <<'FRONTIER_BYTES'

FRONTIER_BYTES
base64 -d > gcp_worker.py <<'FRONTIER_BYTES'

FRONTIER_BYTES
base64 -d > gcp_artifacts.py <<'FRONTIER_BYTES'

FRONTIER_BYTES
/usr/bin/python3 /work/frontier/gcp_worker.py run /work/frontier/config.json
